t.script:
document.addEventListener('DOMContentLoaded', function() {
    if (typeof ck === 'undefined') {
        console.warn("Credit Key SDK not loaded.");
        return;
    }

    const publicKey = "";
    if (!publicKey) {
        console.warn("Credit Key: missing public key.");
        return;
    }

    const state = "";
    const env = (state === "enabled") ? "production" : "staging";

    // Custom selector from backend (may be empty)
    const rawAnchorSelector = "";
    let anchorSelector = rawAnchorSelector.trim();

    // If they just typed a bare word (e.g. "myclass"), treat it as a class selector
    if (anchorSelector && !anchorSelector.startsWith('.') && !anchorSelector.startsWith('#') && !anchorSelector.includes(' ')) {
        anchorSelector = '.' + anchorSelector;
    }

    // Default anchor: the price section wrapper
    if (!anchorSelector) {
        anchorSelector = "div.o_wsale_product_details_content_section_price";
    }

    const wrapper = document.getElementById('credit_key_product_wrapper');
    const anchorEl = document.querySelector(anchorSelector);

    if (anchorEl && wrapper) {
        anchorEl.insertAdjacentElement('afterend', wrapper);
    } else if (!anchorEl) {
        console.warn("Credit Key: anchor selector not found:", anchorSelector);
    }

    // Price selector (static or could be made configurable if you want)
    const selector = "#product_details .oe_price";
    const priceEl = document.querySelector(selector);
    if (!priceEl) {
        console.warn("Credit Key: Price selector not found:", selector);
        return;
    }

    const priceText = priceEl.innerText.replace(/[^\d.]/g, '');
    const productPrice = parseFloat(priceText);
    if (!productPrice || productPrice <= 0) {
        console.warn("Credit Key: No valid price detected");
        return;
    }

    const client = new ck.Client(publicKey, env);
    const charges = new ck.Charges(productPrice, 0, 0, 0, productPrice);

    const container = document.getElementById('credit_key_product');
    if (container) {
        container.innerHTML = client.get_pdp_display(charges);
    }
});

document.addEventListener('DOMContentLoaded', function() {
    if (typeof ck === 'undefined') {
        console.warn("Credit Key SDK not loaded.");
        return;
    }

    // --- Provider config from QWeb ---
    const publicKey = "";
    if (!publicKey) {
        console.warn("Credit Key: missing public key.");
        return;
    }

    const state = "";
    const env = (state === "enabled") ? "production" : "staging";

    // Custom selector from backend (may be empty)
    const rawAnchorSelector = "";
    let anchorSelector = rawAnchorSelector.trim();

    if (rawAnchorSelector && !rawAnchorSelector.startsWith('.') && !rawAnchorSelector.startsWith('#') && !rawAnchorSelector.includes(' ')) {
        anchorSelector = '.' + rawAnchorSelector;
    }

    if (!anchorSelector) {
        anchorSelector = "a[name='website_sale_main_button']";
    }

    const wrapper = document.getElementById('credit_key_cart_wrapper');
    const anchorEl = document.querySelector(anchorSelector);

    if (anchorEl && wrapper) {
        // Move the whole wrapper AFTER the anchor element
        anchorEl.insertAdjacentElement('afterend', wrapper);
    } else if (!anchorEl) {
        console.warn("Credit Key: anchor selector not found:", anchorSelector);
    }

    const totalSelector = "tr[name='o_order_total'] .oe_currency_value, tr[name='o_order_total'] .monetary_field";
    const totalEl = document.querySelector(totalSelector);

    if (!totalEl) {
        console.warn("Cart total element not found using selector:", totalSelector);
        return;
    }

    const totalText = totalEl.innerText.replace(/[^\d.]/g, '');
    const total = parseFloat(totalText) || 0;
    if (total <= 0) {
        console.warn("Credit Key: No valid total detected");
        return;
    }

    const client = new ck.Client(publicKey, env);
    const charges = new ck.Charges(total, 0, 0, 0, total);

    const container = document.getElementById('credit_key_cart');
    if (container) {
        container.innerHTML = client.get_cart_display(charges, 'center', 'center');
    }
});
